func (p *Parser) parseTableArgExpr(pos Pos) (Expr, error) {
	// Special case: if we see an identifier followed by '(', it's a nested table function
	if p.matchTokenKind(TokenKindIdent) {
		// Peek ahead to see if there's a left paren
		nextToken, err := p.lexer.peekToken()
		if err == nil && nextToken != nil && nextToken.Kind == TokenKindLParen {
			// This is a nested table function like numbers(plus(1, 2))
			ident, err := p.parseIdent()
			if err != nil {
				return nil, err
			}
			argsExpr, err := p.parseTableArgList(pos)
			if err != nil {
				return nil, err
			}
			return &TableFunctionExpr{
				Name: ident,
				Args: argsExpr,
			}, nil
		}
	}

	// For all other cases (literals, subqueries, expressions, etc.), parse as a general expression
	return p.parseExpr(pos)
}
